SELECT CAST(COUNT(DISTINCT CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2017 AND 2019 AND d.diagnosis_code = 'ACS' THEN a.hadm_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.hadm_id), 0) AS proportion_of_admissions, COUNT(DISTINCT CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2017 AND 2019 AND d.diagnosis_code = 'ACS' THEN a.hadm_id END) AS number_of_admissions, COUNT(DISTINCT CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2017 AND 2019 AND d.diagnosis_code = 'ACS' AND l.value <= 0.04 THEN a.hadm_id END) AS number_of_admissions_with_normal_troponin_t, COUNT(DISTINCT CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2017 AND 2019 AND d.diagnosis_code = 'ACS' AND l.value > 0.04 AND l.value <= 0.1 THEN a.hadm_id END) AS number_of_admissions_with_borderline_troponin_t, COUNT(DISTINCT CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2017 AND 2019 AND d.diagnosis_code = 'ACS' AND l.value > 0.1 THEN a.hadm_id END) AS number_of_admissions_with_elevated_troponin_t FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id LEFT JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.anchor_age = 72;